class Solution:
    def eventualSafeNodes(self, graph: list[list[int]]) -> list[int]:
        n = len(graph)
        def ok(s):
            path = set()
            def dfs(u):
                if u in path:
                    return False
                path.add(u)
                for v in graph[u]:
                    if not dfs(v):
                        path.remove(u)
                        return False
                path.remove(u)
                return True
            return dfs(s)
        return [i for i in range(n) if ok(i)]

