class Solution:
    def eventualSafeNodes(self, graph: list[list[int]]) -> list[int]:
        n = len(graph)
        state = [0] * n
        def dfs(u):
            if state[u]:
                return state[u] == 2
            state[u] = 1
            for v in graph[u]:
                if state[v] == 1 or not dfs(v):
                    state[u] = 3
                    return False
            state[u] = 2
            return True
        return [i for i in range(n) if dfs(i)]

